"""V4: borderless illustrated rooms. Data and supplied art are kept intact."""
from pathlib import Path
from html import escape as e
import json
import data as d

ROOT=Path(__file__).resolve().parents[1]

def arrow(back=False):
    return '<svg class="arrow" viewBox="0 0 60 20" aria-hidden="true"><path d="'+('M58 10H3M11 3 3 10l8 7' if back else 'M2 10h55M49 3l8 7-8 7')+'"/></svg>'

def action(label,href=None,attrs='',cls=''):
    tag='a' if href else 'button'
    return f'<{tag} class="action {cls}" '+(f'href="{href}" ' if href else '')+f'{attrs}><span>{label}</span>{arrow()}</{tag}>'

def picture(src,alt='',cls='',priority=False):
    return f'<img src="{src}" alt="{e(alt)}" class="{cls}" '+('fetchpriority="high"' if priority else 'loading="lazy"')+'>'

def mast(en,name,number=''):
    return f'<div class="chapter-heading reveal"><span class="eyebrow">{en}</span><h1>{name}</h1>'+ (f'<span class="chapter-number">{number}</span>' if number else '')+'</div>'

def entrance():
    return f'''<div class="entry-scene scene">{picture('assets/art/alley.webp',priority=True)}</div><section class="entry-composition"><p class="eyebrow reveal">VEILHAUN</p><h1 class="entry-wordmark reveal">{picture('assets/ui/wordmark.webp','골목 시술소',priority=True)}</h1><div class="entry-action reveal">{action('입장',attrs='id="enter"')}<p>만 19세 이상입니다</p></div><p class="entry-age reveal">19+ · 만 19세 미만은 입장할 수 없습니다</p></section><div class="entry-credit">글 · 설정 {e(d.CONFIG['AUTHOR'])}</div>'''

def home():
    menu=''.join(f'<li><span class="menu-order">0{i}</span><h3>{e(n)}<small>{e(t)}</small></h3><span class="menu-price">{e(p)}</span></li>' for i,(n,p,t) in enumerate(d.MENUS,1))
    reservations=''.join(f'<li><time>{e(r.get("time",""))}</time> {e(r.get("name",""))} · {e(r.get("menu",""))}</li>' for r in d.CONFIG['RESERVATIONS']) or '<li>등록된 예약이 없습니다.</li>'
    rumors=''.join(f'<li><span>0{i}</span><p>{e(s)}</p></li>' for i,s in enumerate(d.RUMORS[:4],1))
    return f'''<section class="reception-hero"><div class="scene">{picture('assets/art/reception.webp',priority=True)}</div><div class="reception-title reveal"><span class="eyebrow">RECEPTION</span><h1>접수대</h1><div class="hero-jumps"><a href="#menu">시술 메뉴</a><a href="#ledger">오늘의 장부</a><a href="#rumors">골목 소문</a></div></div><div class="reception-status"><span>영업중</span></div><button id="partition" class="partition-link">칸막이 너머<span>듣기</span></button><q id="voice" class="ambient-voice" aria-live="polite" hidden></q></section><div class="reception-folio paper-field"><section id="menu" class="menu-page reveal"><span class="eyebrow">THE MENU</span><h2>시술 메뉴</h2><ol class="treatment-menu">{menu}</ol><p class="handwriting">{e(d.COPY['menu_note'])}</p><small class="currency">{e(d.COPY['currency'])}</small></section><section id="ledger" class="ledger-page reveal"><span class="eyebrow">TODAY</span><h2>오늘의 장부</h2><p class="ledger-date" data-date></p><ul class="reservation-lines">{reservations}</ul><h3>골목의 평판</h3><ol class="reputation">{''.join(f'<li class="{"current" if i==0 else ""}">{e(x)}</li>' for i,x in enumerate(d.REPUTATION))}</ol>{action('대기실', 'characters.html')}</section><section id="rumors" class="rumor-page reveal"><div><span class="eyebrow">AROUND THE ALLEY</span><h2>골목 소문</h2></div><ol>{rumors}</ol></section></div>'''

def characters():
    people=''.join(f'''<a class="portrait-leaf reveal" data-group="{e(ch['group'])}" href="char/{ch['slug']}.html" style="--order:{i};--focus:{[51,84,75,80,11][i]}%"><div class="portrait-leaf-art">{picture(ch['portrait'],ch['name'],priority=i<2)}<div class="leaf-detail"><p>{e(ch['hook'])}</p><span>카르테 열기 {arrow()}</span></div></div><div class="leaf-caption"><span class="leaf-number">0{i+1}</span><div><h2>{e(ch['name'])}</h2><p>{e(ch['race'])} · {e(ch['age'])} · {e(ch['group'])}</p></div></div></a>''' for i,ch in enumerate(d.CHARACTERS))
    return f'''{mast('WAITING ROOM','대기실')}<div class="roster-filters reveal" aria-label="인물 분류"><button data-filter="전체" aria-pressed="true">모두</button><button data-filter="직원" aria-pressed="false">직원</button><button data-filter="손님" aria-pressed="false">손님</button></div><section class="portrait-gallery" aria-label="인물 카르테">{people}</section><div class="gallery-bottom reveal"><span>직원 2 · 손님 3</span><div><button class="gallery-step" data-gallery-step="-1" aria-label="이전 인물">{arrow(True)}</button><button class="gallery-step" data-gallery-step="1" aria-label="다음 인물">{arrow()}</button></div></div>'''

def chart(ch):
    i=d.CHARACTERS.index(ch)
    tabs=''.join(f'<button data-expression="{n}" aria-pressed="{str(n==0).lower()}">{e(name)}</button>' for n,name in enumerate(d.EXPRESSIONS))
    reactions=ch['reactions'].split(' / ')
    vals=[ch['collapse'],reactions[0],reactions[1].split(': ',1)[-1],reactions[2].split(': ',1)[-1]]
    details=''.join(f'<div><dt>{e(d.COPY[k])}</dt><dd>{e(v)}</dd></div>' for k,v in zip(['collapse','stop','ask','jealous'],vals))
    relations=''.join(f'<li>{e(x)}</li>' for x in d.RELATIONS if ch['name'] in x)
    return f'''<section class="portrait-study"><div class="study-visual reveal"><button class="portrait-zoom" aria-label="그림 크게 보기">{picture('../'+ch['portrait'],ch['name'],'study-image',True)}<span>크게 보기</span></button><div class="image-pager"><button id="expr-prev" aria-label="이전 표정">{arrow(True)}</button><span id="expression-title" aria-live="polite">첫등장</span><button id="expr-next" aria-label="다음 표정">{arrow()}</button></div></div><div class="study-heading reveal"><a class="back-link" href="../characters.html">{arrow(True)}대기실</a><span class="eyebrow">CHART / {ch['code']}</span><h1>{e(ch['name'])}</h1><p class="study-meta">{e(ch['race'])} · {ch['age']} · {e(ch['group'])}</p><p>{e(ch['role'])}</p><blockquote>“{e(ch['hook'])}”</blockquote><nav class="expression-tabs" aria-label="감정 선택">{tabs}</nav><div id="variant-thumbs" aria-label="표정 변형"></div></div></section><article class="character-record paper-field"><section class="record-intro reveal"><span class="eyebrow">PROFILE</span><h2>인물 기록</h2><p>{e(ch['description'])}</p></section><section class="record-map reveal"><div><span class="eyebrow">KNOTS</span><h2>결 지도</h2><p>{e(ch['knots'])}</p><div class="text-tabs"><button data-facing="front" aria-pressed="true">정면</button><button data-facing="back" aria-pressed="false">뒷면</button></div><p id="knot-label" aria-live="polite">{e(d.COPY['knots'])}</p></div><div class="body-map"><svg viewBox="0 0 200 300" aria-label="결 자리 실루엣" role="img"><circle cx="100" cy="46" r="23"/><path d="M85 70Q60 74 52 94L36 163Q37 174 47 169L68 112 70 174 59 265Q63 279 74 269L99 193 125 269Q136 277 140 265L129 174 131 112 153 169Q164 174 164 161L147 94Q137 74 115 70Z"/></svg><div id="map-dots"></div></div></section><section class="record-boundary reveal"><h3>첫 허용선</h3><ol>{''.join(f'<li class="{"unlocked" if n<(2 if ch["code"]=="E" else 1) else ""}"><span>0{n+1}</span>{e(x)}</li>' for n,x in enumerate(d.BOUNDARIES))}</ol><dl class="reactions">{details}</dl></section><section class="record-quotes reveal">{''.join('<blockquote>“'+e(q)+'”</blockquote>' for q in ch['quotes'])}</section><section class="record-notes reveal"><details><summary>외형 · 말투</summary><p>{e(ch['appearance'])}</p><p>{e(ch['speech'])}</p></details><h3>관계</h3><ul>{relations}</ul></section><nav class="record-pagination">{action(d.CHARACTERS[(i-1)%5]['name'],d.CHARACTERS[(i-1)%5]['slug']+'.html')}{action(d.CHARACTERS[(i+1)%5]['name'],d.CHARACTERS[(i+1)%5]['slug']+'.html')}</nav></article>'''

def rules():
    depths=''.join(f'<li><span>0{i}</span><div><h3>{e(n)}</h3><p>{e(t)}</p></div></li>' for i,(n,t) in enumerate(d.DEPTHS,1))
    return f'''<section class="alchemy-portrait reveal"><span class="eyebrow">STILL ROOM</span><h1>조향실</h1><div class="alchemy-image">{picture('assets/art/perfumery.webp',priority=True)}</div><div class="bottle-shelf">{''.join(f'<button class="bottle {key}" data-oil="{key}" aria-pressed="false"><span class="bottle-art" aria-hidden="true"></span><span>{name}</span></button>' for key,name in [('calm','진정'),('warm','온열'),('unknown','?')])}</div><p id="oil-note" aria-live="polite">향유 선택</p></section><section class="open-notebook reveal"><span class="eyebrow">REINA’S NOTES</span><h2>조향 노트</h2><nav class="notebook-tabs" aria-label="노트 페이지"><button data-book="0" aria-pressed="true"><i>01</i>결</button><button data-book="1" aria-pressed="false"><i>02</i>달아오름</button><button data-book="2" aria-pressed="false"><i>03</i>관계</button></nav><div class="book-leaf"><section data-book-page="0"><p class="notebook-definition">{e(d.COPY['knots_definition'])}</p><ol class="depths">{depths}</ol><p class="handwriting">{e(d.COPY['knots_progress'])}</p></section><section data-book-page="1" hidden><h3>달아오름</h3><div class="heat-flame" aria-hidden="true"><i></i><i></i><i></i></div><nav class="heat-steps">{''.join(f'<button data-heat="{i}" aria-pressed="{str(i==0).lower()}">{e(x)}</button>' for i,x in enumerate(d.HEAT))}</nav><p class="heat-label">평온</p></section><section data-book-page="2" hidden><h3>허용선</h3><ol class="note-stages">{''.join('<li>'+e(x)+'</li>' for x in d.BOUNDARIES)}</ol><h3>관계</h3><p class="relation-stages">{' · '.join(d.RELATION_STAGES)}</p><p class="currency">{e(d.COPY['currency'])}</p></section></div><div class="book-pager"><button data-book-step="-1" aria-label="노트 이전 장">{arrow(True)}</button><span id="book-count">01 / 03</span><button data-book-step="1" aria-label="노트 다음 장">{arrow()}</button></div></section>'''

def city():
    p=d.PLACES[0]
    places=''.join(f'<button data-place="{i}" aria-pressed="{str(i==0).lower()}"><i>0{i+1}</i><span>{e(x["name"])}</span></button>' for i,x in enumerate(d.PLACES))
    pins=''.join(f'<button class="map-pin" data-place="{i}" style="--x:{x}%;--y:{y}%" aria-label="{e(p["name"])}"><i></i><span>{e(p["name"])}</span></button>' for i,(p,(x,y)) in enumerate(zip(d.PLACES,[(15,27),(48,40),(72,17),(82,68),(24,72),(51,85)])))
    return f'''{mast('VEILHAUN','베일하운')}<div class="city-panorama reveal">{picture('images/B/'+p['code']+'.webp',p['name'],'city-picture',True)}</div><div class="city-composition"><section class="place-story reveal"><span id="place-number">01</span><div><h2 id="place-name">{e(p['name'])}</h2><p id="place-text">{e(p['text'])}</p><p id="place-guest"></p></div></section><nav class="place-index reveal" aria-label="도시 장소">{places}</nav></div><div class="city-foot">{action('지도 펼치기',attrs='data-open="atlas"')}</div><dialog id="atlas" class="atlas-dialog"><form method="dialog"><button class="close-text">닫기</button></form><div class="atlas-art">{picture('assets/art/atlas.webp','베일하운 장소 개념도')}{pins}</div><p>장소를 탐색하는 개념도</p></dialog>'''

def treatment():
    link=action('들어가기',e(d.CONFIG['MASA_URL'])) if d.CONFIG['MASA_URL'] else '<p class="unavailable">준비 중</p>'
    return f'''<div class="treatment-scene scene">{picture('images/B/T.webp','시술실','treatment-picture',True)}</div><div class="drapery left" aria-hidden="true"></div><div class="drapery right" aria-hidden="true"></div><section class="treatment-title reveal"><span class="eyebrow">TREATMENT</span><h1>시술실</h1><p>{e(d.COPY['treatment_note'])}</p>{action('커튼 열기',attrs='id="draw-curtain" aria-expanded="false"')}<div class="treatment-destination" hidden>{link}</div></section>'''

def start():
    modes=''.join(f'<button data-mode="{key}" aria-pressed="{str(i==0).lower()}"><i>0{i+1}</i><strong>{e(name)}</strong><span>{e(desc)}</span></button>' for i,(key,name,desc) in enumerate(d.MODES))
    link=action('작품으로 들어가기',e(d.CONFIG['CRACK_URL'])) if d.CONFIG['CRACK_URL'] else '<p class="unavailable">작품 링크 준비 중</p>'
    return f'''{mast('OPENING','개업')}<div class="opening-composition"><section class="opening-choice reveal"><nav class="opening-modes" aria-label="시작 모드">{modes}</nav><form id="free-form" hidden><label>경과일<input name="day" type="number" min="0" max="99999" value="0"></label><label>소지금<input name="money" maxlength="120"></label><label>평판<select name="rep">{''.join('<option>'+e(x)+'</option>' for x in d.REPUTATION)}</select></label><label class="full">아는 인물과 관계<textarea name="relations" maxlength="1000"></textarea></label>{action('출발 상태 복사',attrs='type="submit"')}<output id="copy-status" aria-live="polite"></output><textarea id="copy-fallback" aria-label="복사할 출발 상태" readonly hidden></textarea></form></section><article class="opening-preview reveal"><span class="eyebrow">PREVIEW</span><h2>크랙 출력 견본</h2><div class="sample-panorama">{picture('images/B/R.webp','접수대')}</div><div id="prologue"><p>프롤로그 미등록</p></div><details><summary>정보창</summary><pre>{e(d.STATUS_TEMPLATE)}</pre></details><details><summary>플레이 안내</summary><h3>유저노트에 적을 것</h3><p>{e(d.COPY['unwritten'])}</p><h3>단축어</h3><p>{e(d.COPY['unwritten'])}</p></details>{link}</article></div>'''

def write_page(filename,page,body,char=None):
    prefix='../' if '/' in filename else ''
    label=char['name'] if char else dict((r[0],r[1]) for r in d.ROOMS).get(page,'입구')
    payload=dict(config=d.CONFIG,characters=d.CHARACTERS,rumors=d.RUMORS,voices=d.VOICES,places=d.PLACES,expressions=d.EXPRESSIONS,copy=d.COPY,knots=d.KNOT_MAP,page=page,character=char['slug'] if char else None,prefix=prefix)
    for ch in payload['characters']:
        ch['gallery']=[[ch['portrait']] if (ROOT/ch['portrait']).is_file() else []]+[[f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp" for n in range(g['start'],g['end']+1) if (ROOT/f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp").is_file()] for g in d.EXPRESSION_GROUPS[1:]]
    nav=''.join(f'<a href="{prefix}{slug}.html" data-menu-image="{prefix}images/B/{bg}.webp" {"aria-current=\"page\"" if page==slug or page=="chart" and slug=="characters" else ""}><i>0{i}</i><span>{name}</span><small>{en}</small></a>' for i,(slug,name,en,bg) in enumerate(d.ROOMS,1))
    guard='' if page=='index' else f'<script src="{prefix}assets/guard.js"></script>'
    light=page in ['characters','rules','city','start']
    html=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#211b16"><meta name="description" content="골목 시술소. 인물, 시술, 조향 노트와 베일하운."><title>{e(label)} | 골목 시술소</title>{guard}<link rel="icon" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/fonts/pretendard/pretendard.css"><link rel="stylesheet" href="{prefix}assets/experience.css?v=4"><script id="site-data" type="application/json">{json.dumps(payload,ensure_ascii=False).replace('</','<\\/')}</script><script defer src="{prefix}assets/experience.js?v=4"></script></head><body class="page-{page} {'light-page' if light else 'dark-page'}"><a href="#main" class="skip-link">본문으로 건너뛰기</a><header class="masthead"><a class="signature" href="{prefix}{'index' if page=='index' else 'home'}.html">골목 시술소<small>VEILHAUN</small></a><button id="menu-open" class="menu-toggle"><span>둘러보기</span><i aria-hidden="true"></i></button></header><main id="main">{body}</main><footer class="site-foot"><button id="sound" aria-pressed="false">효과음</button><button id="bell">소문 듣기</button><button data-open="directory">방 이동</button><span class="current-room">{e(label)}</span></footer><dialog id="directory" class="directory-dialog"><form method="dialog"><button class="close-text">닫기 {arrow()}</button></form><div class="directory-title"><span class="eyebrow">THE HOUSE</span><h2>둘러보기</h2></div><nav>{nav}</nav><div class="directory-view">{picture(prefix+'assets/art/reception.webp','',priority=False)}</div><a href="{prefix}index.html" class="directory-exit" data-exit>입구로 나가기</a></dialog><dialog id="art-lightbox" class="lightbox" aria-label="그림 크게 보기"><form method="dialog"><button class="close-text">닫기</button></form><img alt=""></dialog><dialog id="rumor-dialog" class="rumor-dialog"><form method="dialog"><button class="close-text">닫기</button></form><span class="eyebrow">AROUND THE ALLEY</span><h2>골목 소문</h2><p id="rumor-text"></p>{action('다음 소문',attrs='id="rumor-next"')}</dialog><div class="scene-transition" aria-hidden="true"><span>골목 시술소</span></div></body></html>'''
    if any(x in html for x in ['\u2013','\u2014']):raise ValueError('Forbidden dash in '+filename)
    dest=ROOT/filename
    dest.parent.mkdir(exist_ok=True)
    dest.write_text(html,encoding='utf-8')
